<?php require __DIR__.'/../includes/bootstrap.php';if(!events_schema_ready()){app_header('Events');?><section class="form-card"><h1>Events are not installed</h1><?php if((user()['role']??'')==='admin'):?><a class="button primary" href="../upgrade-events.php">Install Events</a><?php endif?></section><?php app_footer();exit;}$q=trim($_GET['q']??'');$type=trim($_GET['type']??'');$sql="SELECT e.*,u.display_name owner_name,(SELECT COUNT(*) FROM event_attendees a WHERE a.event_id=e.id AND a.attendee_status IN ('registered','approved','checked_in')) attendee_count FROM events e JOIN users u ON u.id=e.owner_user_id WHERE e.status='approved' AND e.visibility='public'";$args=[];if($q!==''){$sql.=' AND (e.title LIKE ? OR e.description LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}if($type!==''){$sql.=' AND e.event_type=?';$args[]=$type;}$sql.=' ORDER BY e.is_featured DESC,e.starts_at ASC';$s=db()->prepare($sql);$s->execute($args);$events=$s->fetchAll();app_header('Events');?>
<section class="dashboard-hero"><p class="eyebrow">MULTIVERSE SCHEDULE</p><h1>Events</h1><p>Panels, signings, workshops, streams, tournaments, meetups, and community gatherings.</p><form class="hero-search" method="get"><input name="q" value="<?=e($q)?>" placeholder="Search events"><select name="type"><option value="">All types</option><?php foreach(event_type_options() as $k=>$v):?><option value="<?=e($k)?>" <?=$type===$k?'selected':''?>><?=e($v)?></option><?php endforeach?></select><button>Search</button></form><?php if(user()):?><p><a class="button primary" href="create.php">Create Event</a> <a class="button ghost" href="dashboard.php">Manage My Events</a></p><?php endif?></section>
<section class="event-grid"><?php foreach($events as $event):?><article class="event-card"><?php if($event['banner_path']):?><img class="event-card-image" src="<?=e(base_url($event['banner_path']))?>" alt=""><?php endif?><div class="event-card-body"><p class="eyebrow"><?=e(strtoupper(event_type_options()[$event['event_type']]??$event['event_type']))?></p><h2><a href="view.php?slug=<?=urlencode($event['slug'])?>"><?=e($event['title'])?></a></h2><p><strong><?=e(event_date_label($event))?></strong></p><p><?=e($event['subtitle']?:mb_strimwidth((string)$event['description'],0,140,'…'))?></p><div class="pill-row"><span class="pill"><?=e(ucfirst($event['format']))?></span><span class="pill"><?=(int)$event['attendee_count']?> attending</span></div></div></article><?php endforeach?><?php if(!$events):?><div class="empty-state"><h2>No events found</h2><p>The schedule is waiting for its first approved event.</p></div><?php endif?></section><?php app_footer();
